var equalToDescendants = function(root) {
  let ans = 0;
  const dfs = (node) => {
    if (!node) return 0;
    const leftSum = dfs(node.left);
    const rightSum = dfs(node.right);
    if (node.val === leftSum + rightSum) ans++;
    return leftSum + rightSum + node.val;
